<details>
  <summary><b>Use it from CloudFlare Workers (new!)</b></summary>

Use the new `generic` bundle as an ESM import.

> Full sample available at [`./examples/fetch/workers/axios-worker.mjs`](https://github.com/sgammon/axios/blob/feat/fetch-adapter/examples/fetch/workers/axios-worker.mjs)

#### Module-style workers:
```js
import axios from "axios/generic";

async function handler(request) {
  // use axios as normal
  return await axios({ /* ... */ }.then(response => {
    // make sure to rewrite into a Fetch response if you're returning directly
    return new Response(response.data, {
        status: response.status,
        statusText: response.statusText,
        headers: applyCorsHeaders(response.headers),
    });
  });
}

export default {
    async fetch(request) {
        return await handler(request);
    },
};
```

#### Event-style workers:
```js
import axios from "axios/generic";

async function handler(request) {
  // use axios as normal
  return await axios({ /* ... */ }.then(response => {
    // make sure to rewrite into a Fetch response if you're returning directly
    return new Response(response.data, {
        status: response.status,
        statusText: response.statusText,
        headers: applyCorsHeaders(response.headers),
    });
  });
}

addEventListener("fetch", event => {
  event.respondWith(handler(event.request))
})
```

